template<class A> typename A::S value(int x){if constexpr(std::is_integral_v<typename A::S>)return x;else return {x,1};}
template<class S> std::uint64_t checksum(S x){if constexpr(std::is_integral_v<S>)return x;else return x.sum;}
template<class A> void run(int n,int q,int mode){
