 else {Tree t(initial);t.reserve(std::size_t(n)+q+1);
 for(int i=0;i<q;++i){auto [l,r]=queries[i];
 if(mode==1)sum+=checksum(t.prod(l,r));
 if(mode==2)t.apply(l,r,i%7+1);
