 if(mode==8)t.reverse(0,n);
 if(mode==9){int m=l+(r-l)/2;t.rotate(l,m,r);}
 if(mode==10){auto x=t.get(l);t.set(r-1,x);}
 if(mode==11)sum+=checksum(t.prod(0,r));
 if(mode==12)sum+=checksum(t.prod(l,n));
 if(mode==13){Tree copy(t);sum+=copy.size();}
